from __future__ import annotations
class DashboardService:
    def __init__(self,accounts,groups,members,blacklist,campaigns,jobs,alerts=None):self.accounts=accounts;self.groups=groups;self.members=members;self.blacklist=blacklist;self.campaigns=campaigns;self.jobs=jobs;self.alerts=alerts
    def get_dashboard_summary(self):
        eligibility=self.members.count_by_eligibility() if hasattr(self.members,"count_by_eligibility") else {}
        return {"accounts":{"total":self.accounts.count_all(),"healthy":self.accounts.count_by_health("HEALTHY"),"cooldown":self.accounts.count_by_health("COOLDOWN"),"restricted":self.accounts.count_by_health("RESTRICTED"),"offline":self.accounts.count_by_health("OFFLINE")},"groups":{"total":self.groups.count_all(),"sources":self.groups.count_sources(),"targets":self.groups.count_targets(),"managed":self.groups.count_managed(),"public":self.groups.count_public(),"private":self.groups.count_private(),"errors":self.groups.count_errors()},"members":{"total":self.members.count_all(),"eligible":eligibility.get("ELIGIBLE",0),"unknown":eligibility.get("UNKNOWN",0),"do_not_contact":eligibility.get("DO_NOT_CONTACT",0),"excluded":self.blacklist.count_all(),"blacklisted":self.blacklist.count("exclusion_type='GLOBAL_BLACKLIST' AND target_group_id IS NULL") if hasattr(self.blacklist,"count") else 0,"bots":self.members.count_bots() if hasattr(self.members,"count_bots") else 0,"deleted":self.members.count_deleted() if hasattr(self.members,"count_deleted") else 0},"campaigns":{"active":self.campaigns.count_active(),"scheduled":self.campaigns.count_scheduled()},"jobs":{"running":self.jobs.count_running()},"alerts":{"critical":self.alerts.count_open("CRITICAL") if self.alerts else 0,"open":self.alerts.count_open() if self.alerts else 0}}
